'use strict';
const $=id=>document.getElementById(id),game=new BirthdayAdventure();
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let held=0,lastTime=0,scale=1,camera=0,walkFrame=0,portraitAllowed=false,started=false;
let pickupTimer=null,toastUntil=0,confettiTimer=null,activePointer=null,noticeTimer=null,lastStepDistance=0;
let audioContext=null,musicTimer=null,muted=false,musicBeat=0,master=null,musicGain=null,notes=new Set();
let loadGeneration=0;
const imageCache=new Map();
const sharedImages=['walk','front','boxes','rock','chests','stems-pink'].map(name=>'assets/'+name+'.webp');
function loadImage(url){if(imageCache.has(url))return imageCache.get(url);const img=new Image();const promise=new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Image loading timed out')),30000);img.onload=async()=>{try{await img.decode();clearTimeout(timer);resolve(img);}catch(error){clearTimeout(timer);reject(error);}};img.onerror=()=>{clearTimeout(timer);reject(new Error('Image could not load'));};img.src=url;}).catch(error=>{imageCache.delete(url);throw error;});imageCache.set(url,promise);return promise;}
function prepareLevel(level){return Promise.all([...sharedImages,'assets/'+forests[level].image].map(loadImage));}
function warmLevel(level){if(level<forests.length)prepareLevel(level).catch(()=>{});}
const screens=['intro','levelCard','play','finale'];
function setScreen(id){screens.forEach(x=>$(x).hidden=x!==id);stopWalking();requestAnimationFrame(resizeWorld);}
function giftList(){return game.gifts.length?game.gifts.map(r=>`<li><span aria-hidden="true">${r.icon}</span>${r.name}</li>`).join(''):'<li class="empty">Our basket is ready for its first surprise.</li>';}
function levelScreen(){setScreen('levelCard');warmLevel(game.level);$('levelTitle').textContent=`Level ${game.level+1}`;$('levelName').textContent=forests[game.level].name.toUpperCase();$('lastPrize').textContent=game.level?`Level ${game.level} completed · ${game.gifts[game.level-1].icon} ${game.gifts[game.level-1].name} won!`:'Let’s find a birthday surprise for Bruno.';$('cardGifts').innerHTML=giftList();$('cardFlowers').textContent=game.gifts.length?`Peep: ${game.bells} bluebell sprigs · Poppy: ${game.tulips} pink tulip stems`:'Our flower baskets are empty for now.';$('enter').textContent=`Enter Level ${game.level+1} →`;$('levelTitle').focus();}
async function landscapeFullscreen(){try{const request=document.documentElement.requestFullscreen||document.documentElement.webkitRequestFullscreen;if(request&&!document.fullscreenElement)await request.call(document.documentElement);if(screen.orientation?.lock)await screen.orientation.lock('landscape');}catch{}checkOrientation();}
function checkOrientation(){const needs=started&&!portraitAllowed&&window.matchMedia('(orientation: portrait) and (max-width: 750px)').matches;$('rotate').hidden=!needs;if(needs)stopWalking();requestAnimationFrame(resizeWorld);}
function start(){if(!game.start())return;started=true;startMusic();levelScreen();landscapeFullscreen();checkOrientation();}
function buildWorld(){const panels=[0,1,2];$('landscape').innerHTML=panels.map((v,i)=>`<img src="assets/${forests[game.level].image}" alt="" style="left:${i*1200}px;transform:${i%2?'scaleX(-1)':'none'}">`).join('');$('boxes').innerHTML=game.boxes.map((b,i)=>`<div id="box${i}" class="box-object ${b.place}" style="left:${b.x-85}px" aria-label="Cardboard box ${b.place==='rock'?'beside a rock':'on a bench'}"><div class="box-art"></div></div>`).join('');$('chest').style.left=CHEST_X+'px';$('chestArt').className='chest-sprite closed';$('chestCaption').textContent='A surprise!';$('actors').classList.remove('facing-front','face-left');$('completionBubble').hidden=true;$('pickup').hidden=true;$('notice').hidden=true;$('controls').hidden=false;$('next').hidden=true;$('levelLabel').textContent=`Level ${game.level+1}`;$('sceneName').textContent=forests[game.level].name;camera=0;walkFrame=0;lastStepDistance=0;toastUntil=0;resizeWorld();updateHUD();draw();}
async function enter(){if(game.phase!=='level'||!$('loading').hidden)return;const generation=++loadGeneration;$('loading').hidden=false;$('loadingMessage').textContent='Image is loading…';$('retryLoading').hidden=true;$('enter').disabled=true;startMusic();try{await prepareLevel(game.level);if(generation!==loadGeneration)return;if(!game.enter())return;setScreen('play');buildWorld();$('loading').hidden=true;$('scene').focus();}catch{if(generation!==loadGeneration)return;$('loadingMessage').textContent='The scenery could not load. Please try again.';$('retryLoading').hidden=false;}finally{$('enter').disabled=false;}}
function resizeWorld(){if($('play').hidden)return;scale=$('scene').clientWidth/1200;if(!scale)return;const h=$('scene').clientHeight/scale;$('world').style.height=h+'px';$('actors').style.setProperty('--actor-size',Math.min(195,h*.53)+'px');draw();}
function stopWalking(){held=0;activePointer=null;$('left').classList.remove('held');$('right').classList.remove('held');}
function canWalk(){return game.phase==='play'&&!$('parent').open&&!$('quiz').open&&$('rotate').hidden&&!document.hidden;}
function beginWalking(direction){if(!canWalk())return;initAudio();held=direction;$('left').classList.toggle('held',direction===-1);$('right').classList.toggle('held',direction===1);}
function draw(){if($('play').hidden)return;camera=Math.max(0,Math.min(WORLD_END-1200,game.x-430));$('world').style.transform=`translateX(${-camera*scale}px) scale(${scale})`;$('actors').style.left=(game.x-135)+'px';$('actors').classList.toggle('face-left',game.direction===-1&&game.phase!=='complete');if(game.distance-lastStepDistance>=38){lastStepDistance=game.distance;footstep();}const frame=reduced?1:Math.floor(game.distance/27)%4;if(frame!==walkFrame||!game.distance){walkFrame=frame;$('peep').style.backgroundPositionX=(frame/3*100)+'%';$('poppy').style.backgroundPositionX=(((frame+2)%4)/3*100)+'%';}game.boxes.forEach((b,i)=>{const el=$('box'+i);if(!el)return;el.classList.toggle('near',b===game.nearBox&&game.phase==='play');el.classList.toggle('collected',b.collected);});if(game.phase==='play'){const near=game.nearBox;$('collect').classList.toggle('ready',!!near||game.atChest);$('collectLabel').textContent=game.atChest?'Open chest':'Collect';$('left').disabled=game.x<=70;$('right').disabled=game.x>=CHEST_X-115;if(performance.now()>toastUntil){const pending=game.boxes.filter(b=>!b.collected);let message;if(near)message='A flower box is close! Press the middle ✋ button to collect.';else if(game.atChest)message=game.found===5?'All five boxes found! Press ✋ to open the treasure chest.':`${5-game.found} flower ${5-game.found===1?'box is':'boxes are'} still behind us. Walk back to find them.`;else if(!pending.length)message='Our flowers are collected. Keep walking forward to the treasure chest!';else {const closest=pending.reduce((a,b)=>Math.abs(a.x-game.x)<Math.abs(b.x-game.x)?a:b);message=closest.x<game.x?'There’s a flower box behind us. Walk back to look for it!':'Keep walking forward. Look beside rocks and on benches for brown boxes.';}if($('status').textContent!==message)$('status').textContent=message;}}}
function tick(now){const dt=lastTime?Math.min((now-lastTime)/1000,.05):0;lastTime=now;if(held&&canWalk()){game.move(held,dt);draw();}else if(game.phase==='play'&&now>toastUntil)draw();requestAnimationFrame(tick);}
function updateHUD(){$('boxCount').textContent=`${game.found} / 5 boxes`;$('bellCount').textContent=`Bluebells: ${game.bells}`;$('tulipCount').textContent=`Pink tulips: ${game.tulips}`;$('prizeCount').textContent=`Gifts: ${game.gifts.length} / 6`;}
function say(message,seconds=2){$('status').textContent=message;toastUntil=performance.now()+seconds*1000;}
function notice(message,seconds=3){$('notice').textContent=message;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{$('notice').hidden=true;},seconds*1000);}
function interact(){if(!canWalk())return;stopWalking();const box=game.collect();if(box){updateHUD();draw();$('pickupFlower').className='stem-sprite '+(box.kind==='tulips'?'tulips':'');$('pickupText').textContent=box.kind==='bells'?'Collected! +3 bluebell sprigs':'Collected! +3 pink tulip stems';$('pickup').hidden=false;say('Flowers found! They’re safely in our baskets.',2);$('notice').hidden=true;clearTimeout(pickupTimer);pickupTimer=setTimeout(()=>$('pickup').hidden=true,1600);playPickup();return;}if(game.atChest){if(game.found<5){const msg=`You need to collect flowers from all five boxes to open the treasure chest. ${5-game.found} still to find!`;say(msg,3);notice(msg,4);return;}showQuiz();return;}say('Walk closer to a cardboard box, then press the middle ✋ button.',2.5);}
function showQuiz(){const q=game.selectQuestion();if(!q)return;stopWalking();$('questionTitle').textContent=q.title;$('message').textContent=q.text;$('prompt').textContent=q.q;$('feedback').textContent='';$('hint').textContent=game.skills[q.topic].misses?topics[q.topic].hint:'Take your time. What would help our friends stay safe?';$('choices').innerHTML=q.options.map((o,i)=>`<button class="choice" data-answer="${i}"><b>${String.fromCharCode(65+i)}</b><span>${o}</span></button>`).join('');$('choices').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(+b.dataset.answer,b));$('quiz').showModal();}
function closeQuiz(){game.closeQuestion();$('quiz').close();cancelSpeech();$('collect').focus();draw();}
function answer(i,button){const good=game.answer(i);if(good===null)return;if(!good){button.disabled=true;button.classList.add('retry');$('hint').textContent=topics[game.question.topic].hint;$('feedback').textContent='Let’s think together. Try another choice—you can do it!';return;}cancelSpeech();$('quiz').close();stopWalking();$('actors').classList.add('facing-front');$('actors').classList.remove('face-left');$('completionBubble').innerHTML=`Level ${game.level+1} completed!<small>${rewards[game.level].icon} ${rewards[game.level].name} won!</small>`;$('completionBubble').hidden=false;$('chestArt').className='chest-sprite open';$('chestCaption').textContent=rewards[game.level].icon+' '+rewards[game.level].name;$('controls').hidden=true;$('next').hidden=false;$('next').textContent=game.level===5?'Visit Bruno →':`Next: Level ${game.level+2} →`;say(game.question.why,30);updateHUD();draw();celebrate();confetti();warmLevel(game.level+1);if(game.level===5)loadImage('assets/finale.webp').catch(()=>{});$('next').focus();}
function next(){if(!game.next())return;clearTimeout(pickupTimer);$('pickup').hidden=true;$('confetti').replaceChildren();if(game.phase==='finale'){setScreen('finale');$('finalGifts').innerHTML=giftList();celebrate();}else levelScreen();}
function restart(){loadGeneration++;$('loading').hidden=true;stopWalking();clearTimeout(pickupTimer);clearTimeout(confettiTimer);$('quiz').close();$('parent').close();cancelSpeech();game.reset();game.start();started=true;$('confetti').replaceChildren();levelScreen();startMusic();checkOrientation();}
function confetti(){const host=$('confetti');host.replaceChildren();for(let i=0;i<(reduced?16:48);i++){const c=document.createElement('i');c.className='confetto';c.style.left=Math.random()*100+'%';c.style.background=['#e4b458','#8fa8c7','#cc8f9b','#91aa6f'][i%4];c.style.animationDelay=Math.random()*.35+'s';if(reduced)c.style.top=10+Math.random()*70+'%';host.appendChild(c);}clearTimeout(confettiTimer);confettiTimer=setTimeout(()=>host.replaceChildren(),3000);}
// Audio is synthesised locally after the first user gesture. No media requests.
async function initAudio(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return false;if(!audioContext||audioContext.state==='closed'){audioContext=new C();master=audioContext.createGain();master.gain.value=.7;master.connect(audioContext.destination);musicGain=audioContext.createGain();musicGain.gain.value=1;musicGain.connect(master);}if(audioContext.state!=='running')await audioContext.resume();return audioContext.state==='running';}catch{return false;}}
function soundLabel(){const playing=!muted&&audioContext?.state==='running'&&musicTimer!==null;$('sound').textContent=playing?'♫ Music off':'♫ Music on';$('sound').setAttribute('aria-pressed',String(playing));}
function tone(freq,time,duration,volume,isMusic=false,wave='sine'){if((muted&&isMusic)||!audioContext||document.hidden)return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=wave;o.frequency.value=freq;g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+(wave==='triangle'?.008:.035));g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(isMusic?musicGain:master);o.start(time);o.stop(time+duration+.04);notes.add(o);o.onended=()=>{notes.delete(o);o.disconnect();g.disconnect();};}
function musicBar(){if(muted||document.hidden||!audioContext)return;const melodies=[[392,493.88,587.33,493.88],[329.63,392,493.88,392],[349.23,440,523.25,440],[293.66,369.99,440,369.99]],m=melodies[musicBeat++%4],t=audioContext.currentTime+.03;m.forEach((f,i)=>tone(f,t+i*.65,1.05,.018,true));tone(m[0]/2,t,2.4,.012,true);}
async function startMusic(){if(muted||document.hidden)return;if(!await initAudio()){soundLabel();return;}if(muted||document.hidden)return;if(musicTimer===null){musicBar();musicTimer=setInterval(musicBar,2800);}soundLabel();}
function stopAudio(){clearInterval(musicTimer);musicTimer=null;notes.forEach(o=>{try{o.stop();}catch{}});notes.clear();soundLabel();}
async function celebrate(){if(!await initAudio()||document.hidden)return;const t=audioContext.currentTime+.025;musicGain.gain.cancelScheduledValues(t);musicGain.gain.setValueAtTime(.23,t);musicGain.gain.setValueAtTime(.23,t+2.5);musicGain.gain.linearRampToValueAtTime(1,t+3);const melody=[523.25,659.25,783.99,1046.5,783.99,1046.5];melody.forEach((f,i)=>tone(f,t+i*.17,.32,.14,false,'triangle'));[523.25,659.25,783.99,1046.5].forEach(f=>tone(f,t+1.15,1.1,.075,false,'triangle'));[1046.5,1318.51,1567.98].forEach((f,i)=>tone(f,t+1.6+i*.13,.55,.065));}
function playPickup(){initAudio();if(audioContext){tone(659.25,audioContext.currentTime,.22,.035);tone(783.99,audioContext.currentTime+.13,.3,.035);}}
function footstep(){if(audioContext?.state!=='running'||document.hidden||game.phase!=='play')return;const now=audioContext.currentTime;const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='triangle';o.frequency.setValueAtTime(520,now);o.frequency.exponentialRampToValueAtTime(180,now+.045);g.gain.setValueAtTime(.055,now);g.gain.exponentialRampToValueAtTime(.0001,now+.07);o.connect(g);g.connect(master);o.start(now);o.stop(now+.08);notes.add(o);o.onended=()=>{notes.delete(o);o.disconnect();g.disconnect();};}
function cancelSpeech(){window.speechSynthesis?.cancel();if(master&&audioContext)master.gain.setTargetAtTime(.7,audioContext.currentTime,.08);}
function readQuestion(){if(!window.speechSynthesis){$('feedback').textContent='Read-aloud isn’t available here. A grown-up can read with you.';return;}cancelSpeech();if(master&&audioContext)master.gain.setTargetAtTime(.16,audioContext.currentTime,.08);const q=game.question,u=new SpeechSynthesisUtterance(`${q.title}. ${q.text}. ${q.q}. ${q.options.map((x,i)=>String.fromCharCode(65+i)+'. '+x).join('. ')}. Poppy’s hint: ${$('hint').textContent}`);u.lang='en-GB';u.rate=.83;u.onend=()=>{if(master&&audioContext)master.gain.setTargetAtTime(.7,audioContext.currentTime,.08);};u.onerror=e=>{u.onend();if(!['canceled','interrupted'].includes(e.error))$('feedback').textContent='The voice could not start. A grown-up can read with you.';};speechSynthesis.speak(u);}
function bindMovement(button,direction){button.addEventListener('pointerdown',e=>{if(!canWalk())return;e.preventDefault();activePointer=e.pointerId;button.setPointerCapture(e.pointerId);game.move(direction,.1);draw();beginWalking(direction);});button.addEventListener('pointerup',stopWalking);button.addEventListener('pointercancel',stopWalking);button.addEventListener('lostpointercapture',stopWalking);button.addEventListener('click',e=>{if(e.detail===0&&canWalk()){game.move(direction,.1);draw();}});button.addEventListener('contextmenu',e=>e.preventDefault());}
bindMovement($('left'),-1);bindMovement($('right'),1);
window.addEventListener('keydown',e=>{if(!canWalk()||e.altKey||e.ctrlKey||e.metaKey)return;if(['ArrowLeft','a','A','ArrowRight','d','D'].includes(e.key)){e.preventDefault();beginWalking(['ArrowLeft','a','A'].includes(e.key)?-1:1);}else if(e.code==='Space'&&!e.repeat){e.preventDefault();interact();}});
window.addEventListener('keyup',e=>{if(['ArrowLeft','a','A','ArrowRight','d','D'].includes(e.key))stopWalking();});
window.addEventListener('blur',()=>{stopWalking();cancelSpeech();});document.addEventListener('visibilitychange',()=>{stopWalking();if(document.hidden){stopAudio();cancelSpeech();}else if(started)startMusic();});window.addEventListener('resize',checkOrientation);document.addEventListener('fullscreenchange',checkOrientation);
$('retryLoading').onclick=()=>{$('loading').hidden=true;enter();};$('start').onclick=start;$('enter').onclick=enter;$('collect').onclick=interact;$('next').onclick=next;$('again').onclick=restart;$('restart').onclick=restart;$('back').onclick=closeQuiz;$('quizListen').onclick=readQuestion;$('quiz').addEventListener('cancel',e=>{e.preventDefault();closeQuiz();});$('fullscreen').onclick=landscapeFullscreen;$('rotateFullscreen').onclick=landscapeFullscreen;$('portraitContinue').onclick=()=>{portraitAllowed=true;checkOrientation();};
$('sound').onclick=()=>{if(!muted&&musicTimer!==null){muted=true;stopAudio();}else{muted=false;startMusic();}soundLabel();};
$('grown').onclick=()=>{stopWalking();$('report').textContent='This session: '+Object.entries(game.skills).map(([k,s])=>`${topics[k].name}: ${s.correct}/${s.seen} safe first choices`).join(' · ')+'.';$('parent').showModal();};$('closeParent').onclick=()=>$('parent').close();
setScreen('intro');warmLevel(0);soundLabel();requestAnimationFrame(tick);
